SELECT COUNT(*) AS businessCount, IFNULL(SUM(total_price), 0) AS totalPrice, IFNULL(SUM(total_price), 0) AS probabilityPrice FROM crm_business WHERE deleted = 0 AND owner_user_id IN
#{userId}
AND YEAR(create_time) = #{year}
AND end_status = #{endStatus}
AND end_status IS NULL

SELECT b.id AS id, b.name AS name, IFNULL(c.name, '') AS customerName, IFNULL(u.nickname, '') AS ownerUserName, b.deal_time AS dealTime, IFNULL(b.total_price, 0) AS totalPrice, IFNULL(b.total_price, 0) AS probabilityPrice FROM crm_business b LEFT JOIN crm_customer c ON c.id = b.customer_id AND c.deleted = 0 LEFT JOIN system_users u ON u.id = b.owner_user_id WHERE b.deleted = 0 AND b.end_status = 1 AND b.owner_user_id IN
#{userId}
AND YEAR(b.create_time) = #{year}
ORDER BY b.deal_time DESC LIMIT #{offset}, #{pageSize}

SELECT COUNT(*) FROM crm_business WHERE deleted = 0 AND end_status = 1 AND owner_user_id IN
#{userId}
AND YEAR(create_time) = #{year}

SELECT DATE_FORMAT(create_time, '%Y-%m') AS month, COUNT(*) AS businessCount, IFNULL(SUM(total_price), 0) AS totalPrice, IFNULL(SUM(total_price), 0) AS probabilityPrice FROM crm_business WHERE deleted = 0 AND owner_user_id IN
#{userId}
AND YEAR(create_time) = #{year}
AND end_status = #{endStatus}
AND end_status IS NULL
GROUP BY DATE_FORMAT(create_time, '%Y-%m') ORDER BY month
